import Foundation
import PogoReader

/// The raid (PvE) stats of every move: type, power, duration and energy (`Resources/pve-moves.json`, generated by `scripts/fetch-pve-moves.mjs` from the public
/// PokeMiners game master), keyed by the same move ids as `GameMaster.moves`. The game master file the app otherwise reads (PvPoke's) has PvP stats only.
public struct PveMoves {
    public struct Move: Equatable {
        public var type: String
        public var power: Double
        public var durationMs: Double
        /// Energy a fast move gives (positive) or a charged move costs (negative).
        public var energyDelta: Double
        public init(type: String, power: Double, durationMs: Double, energyDelta: Double) { self.type = type; self.power = power; self.durationMs = durationMs; self.energyDelta = energyDelta }
    }

    public let moves: [String: Move]
    /// Max move base power at Max Move level 1: a Max Attack (Max Strike, Max Flare, ...) and a G-Max move. Constants in the generator, not game master data.
    public let maxAttackPower: Double
    public let gmaxPower: Double

    public init(moves: [String: Move], maxAttackPower: Double, gmaxPower: Double) { self.moves = moves; self.maxAttackPower = maxAttackPower; self.gmaxPower = gmaxPower }

    public init(data: Data) throws {
        struct Entry: Decodable { var type: String; var power: Double; var durationMs: Double; var energyDelta: Double }
        struct Power: Decodable { var maxAttack: [Double]; var gmax: [Double] }
        struct File: Decodable { var moves: [String: Entry]; var maxMovePower: Power }
        let file: File
        do { file = try JSONDecoder().decode(File.self, from: data) } catch { throw GameMaster.Failure.unreadable("pve-moves.json: \(error)") }
        moves = file.moves.mapValues { Move(type: $0.type, power: $0.power, durationMs: $0.durationMs, energyDelta: $0.energyDelta) }
        maxAttackPower = file.maxMovePower.maxAttack.first ?? 250
        gmaxPower = file.maxMovePower.gmax.first ?? 350
    }

    /// The bundled move stats. Loaded once per process.
    public static func bundled() throws -> PveMoves { try loaded.get() }
    private static let loaded = Result<PveMoves, Error> {
        guard let url = Bundle.module.url(forResource: "pve-moves", withExtension: "json") else { throw GameMaster.Failure.unreadable("pve-moves.json is missing from the app") }
        return try PveMoves(data: Data(contentsOf: url))
    }
}

/// How strong a picker row is, as the bar and the spoken label say it. Every figure is a share of the best in the game for the slot, 0 to 1 (see `StrengthScale`).
public struct Strength: Equatable {
    public enum Kind: String, Equatable { case damage, bulk, score }
    public var kind: Kind
    /// The copy as it is now; nil when its level or IVs are not read (the bar then has no solid part).
    public var now: Double?
    /// The copy after its suggested upgrade; nil when there is nothing to show (Full strength, no upgrade, or no gain).
    public var after: Double?
    /// A Pokémon the box lacks: the figure is for the species at level 50 with 15/15/15 (kept in `now`).
    public var assumed = false
    /// Score: the figure for the spoken label ("score 87").
    public var score: Int? = nil

    public init(kind: Kind, now: Double?, after: Double?, assumed: Bool = false, score: Int? = nil) {
        self.kind = kind; self.now = now; self.after = after; self.assumed = assumed; self.score = score
    }

    public var barSolid: Double { min(1, max(0, now ?? 0)) }
    public var barEnd: Double { min(1, max(barSolid, after ?? 0)) }
    /// A faint part continues the solid one to the figure after the upgrade.
    public var hasFaint: Bool { barEnd - barSolid > 0.004 }
    /// Nothing to draw: neither figure could be worked out.
    public var isEmpty: Bool { now == nil && after == nil && score == nil }

    static func percent(_ x: Double) -> Int { Int((min(1, max(0, x)) * 100).rounded()) }

    /// For the row's VoiceOver label ("estimated damage 62 percent of the best, 85 percent after upgrade"); nil when there is nothing to say.
    public var spoken: String? {
        if kind == .score { return score.map { "score \($0)" } ?? "score not known" }
        let noun = kind == .damage ? "estimated damage" : "bulk"
        switch (now, after) {
        case let (n?, a?) where hasFaint: return "\(noun) \(Self.percent(n)) percent of the best, \(Self.percent(a)) percent after upgrade"
        case let (n?, _): return "\(noun) \(Self.percent(n)) percent of the best" + (assumed ? ", at level 50 with 15, 15, 15" : "")
        case let (nil, a?): return "\(noun) now not read, \(Self.percent(a)) percent of the best after upgrade"
        default: return "\(noun) not read"
        }
    }

    /// A PvP row with no league score at all (PvPoke does not rank the species there): no bar, and the label says so.
    public static let scoreNotKnown = Strength(kind: .score, now: nil, after: nil)

    /// A PvP score (0 to 100) as one bar with no faint part: the league score is already of the built option.
    public static func score(_ s: Double) -> Strength { Strength(kind: .score, now: min(1, max(0, s / 100)), after: nil, score: Int(s.rounded())) }
}

/// Estimated damage and the picker bars (phone run 2, P1). Pure: the box, the game master and the tables come in as arguments.
public enum DamageEstimate {
    /// A Shadow Pokémon's Attack multiplier; the same-type bonus; the PvP damage bonus.
    public static let shadowAttack = 1.2, stab = 1.2, pvpBonus = 1.3
    /// The defender's defence is (its base Defence + 15) x the level 40 multiplier. It is the same in every Pokémon's figure for a boss, so it cancels in the share of the best
    /// (apart from the floor in the damage formula).
    public static let defenderIV = 15.0, defenderLevel = 40.0
    /// Level and IVs of the "best in the game" Pokémon and of a Pokémon the box lacks.
    public static let bestLevel = 50.0, bestIVs = IVs(atk: 15, def: 15, hp: 15)

    /// Damage of one move: floor(0.5 x power x attack / defence x same-type bonus x effectiveness [x 1.3 in PvP]) + 1.
    public static func damage(power: Double, attack: Double, defence: Double, sameType: Bool, effectiveness: Double, pvp: Bool = false) -> Double {
        (0.5 * power * attack / defence * (sameType ? stab : 1) * effectiveness * (pvp ? pvpBonus : 1)).rounded(.down) + 1
    }

    /// A species' attack stat: (base Attack + Attack IV) x the level's multiplier, x1.2 for a Shadow. nil for a level the table has no multiplier for.
    public static func attackStat(base: BaseStats, ivs: IVs, level: Double, shadow: Bool) -> Double? {
        PogoRules.cpm(level).map { Double(base.atk + ivs.atk) * $0 * (shadow ? shadowAttack : 1) }
    }

    /// Moves named by game master id: the fast move and the charged moves a Pokémon is judged with. nil / empty means "its best".
    public struct Pick: Equatable {
        public var fast: String?
        public var charged: [String]
        public init(fast: String? = nil, charged: [String] = []) { self.fast = fast; self.charged = charged }
    }

    /// The table's move lines as game master move ids. A cell may hold several lines (";"), several fast moves ("Fire Spin or Wing Attack") and several charged moves
    /// ("A + B", "A or B"): "Fire Spin or Wing Attack / Dragon Claw + Blast Burn" is two picks. A name the game master does not know (a Max move, "Dynamax Cannon") gives
    /// nothing for its slot; a trailing "+" (a Mega charged attack) reads as the base move; a bracket ("(Elite)", "(CD)") is dropped. A line that gives no move at all is
    /// counted in `unparsed` and skipped.
    public static func parseLines(_ text: String?, gm: GameMaster) -> (picks: [Pick], unparsed: Int) {
        guard let text, !text.isEmpty else { return ([], 0) }
        let names = moveIdsByName(gm)
        func resolve(_ part: String) -> String? {
            var p = part
            if let open = p.firstIndex(of: "(") { p = String(p[..<open]) }
            p = p.trimmingCharacters(in: .whitespaces)
            if p.hasSuffix("+") { p = String(p.dropLast()) }
            return names[normName(p)]
        }
        var picks = [Pick](), unparsed = 0
        for line in text.components(separatedBy: ";") {
            let halves = line.components(separatedBy: " / ")
            let fasts = (halves.first ?? "").components(separatedBy: " or ").compactMap(resolve)
            let charged = halves.dropFirst().joined(separator: " / ").components(separatedBy: " + ").flatMap { $0.components(separatedBy: " or ") }.compactMap(resolve)
            if fasts.isEmpty && charged.isEmpty { unparsed += 1; continue }
            picks += fasts.isEmpty ? [Pick(fast: nil, charged: charged)] : fasts.map { Pick(fast: $0, charged: charged) }
        }
        return (picks, unparsed)
    }

    private static func normName(_ s: String) -> String { s.lowercased().filter { $0.isLetter || $0.isNumber } }

    /// Move name to id, one id per name by rule, not by dictionary order: the id without `_PLUS`, then the shortest (a plain move before a form-specific
    /// "AEGISLASH_CHARGE_AIR_SLASH"), then the first alphabetically (Aura Wheel's two ids resolve to AURA_WHEEL_DARK).
    static func moveIdsByName(_ gm: GameMaster) -> [String: String] {
        var out = [String: String]()
        for id in gm.moves.keys.sorted() {
            guard let m = gm.moves[id] else { continue }
            let n = normName(m.name)
            guard let have = out[n] else { out[n] = id; continue }
            func rank(_ x: String) -> (Int, Int) { (x.hasSuffix("_PLUS") ? 1 : 0, x.count) }
            if rank(id) < rank(have) { out[n] = id }
        }
        return out
    }

    /// The figures the unreadable move lines cost: how many lines of the tables name no move the game master knows.
    public static func unparsedLineCount(table: TierTable, gm: GameMaster) -> Int {
        table.entries.reduce(0) { $0 + parseLines($1.moves, gm: gm).unparsed }
    }

    /// CP and IVs as the picker row says them: "CP 3,412 · 15/14/15" (Attack/Defence/HP); "CP not read" and "IVs not read" where they are not. `ivs: false` leaves the IVs out
    /// (PvP has its own graded IV line). The spoken form joins with commas.
    public static func cpIvLine(_ e: BoxEntry, ivs showIVs: Bool = true) -> (text: String, spoken: String) {
        let cp = e.row.cp > 0 ? "CP \(HubModel.grouped(e.row.cp))" : "CP not read"
        let cpSpoken = e.row.cp > 0 ? "CP \(e.row.cp)" : "CP not read"
        guard showIVs else { return (cp, cpSpoken) }
        if let v = e.row.ivs { return ("\(cp) · \(v.atk)/\(v.def)/\(v.hp)", "\(cpSpoken), IVs \(v.atk), \(v.def), \(v.hp)") }
        return ("\(cp) · IVs not read", "\(cpSpoken), IVs not read")
    }

    /// The best Gym bulk in the game: level 50, 15/15/15, among released species (no Mega, Shadow or duplicate entry), with the formula `PogoRules.bulk` uses.
    public static func bestGymBulk(gm: GameMaster) -> Double {
        let key = "gym|\(gm.ordered.count)"
        if let v = cached(key) { return v }
        var best = 0.0
        for s in gm.ordered where eligible(s, megas: false) {
            if case .known(let b) = PogoRules.bulk(target: s.id, ivs: bestIVs, level: bestLevel, gm: gm) { best = max(best, b) }
        }
        store(key, best)
        return best
    }

    /// Gym: the bar is the Bulk (now at the copy's level, after at the build's target level) as a share of the best Gym bulk in the game. `row` is the existing `GymRow`
    /// (its `bulk` is already the build's, at the target level, or the copy's level when built); `copy` is nil for a species the box lacks (level 50, 15/15/15).
    public static func gymStrength(copy: BoxEntry?, row: HubSquads.GymRow?, speciesId: String?, gm: GameMaster) -> Strength {
        let best = bestGymBulk(gm: gm)
        guard best > 0 else { return Strength(kind: .bulk, now: nil, after: nil) }
        guard let copy else {
            let b = speciesId.flatMap { PogoRules.bulk(target: $0, ivs: bestIVs, level: bestLevel, gm: gm).value }
            return Strength(kind: .bulk, now: b.map { min(1, $0 / best) }, after: nil, assumed: true)
        }
        let now = PogoRules.bulk(target: copy.row.speciesId, ivs: copy.row.ivs, level: copy.row.level, gm: gm).value.map { min(1, $0 / best) }
        var after = row.flatMap { $0.built ? nil : $0.bulk.value }.map { min(1, $0 / best) }
        // An upgrade is never worse than the copy as it is.
        if let a = after, let n = now, a < n { after = n }
        var s = Strength(kind: .bulk, now: now, after: after)
        if !s.hasFaint && now != nil { s.after = nil }
        return s
    }

    // MARK: eligibility and the shared cache

    /// A game master entry the "best in the game" may name: released as the Collection reads it (`HubCollection`), with stats, and not a Shadow or duplicate entry (a Shadow
    /// is the plain entry with its Attack raised).
    static func eligible(_ s: GameMaster.Species, megas: Bool) -> Bool {
        guard s.baseStats != nil, s.released || HubCollection.releasedInGoDespiteFlag.contains(s.dex), !s.tags.contains("duplicate"), !s.tags.contains("shadow") else { return false }
        return megas || !s.tags.contains("mega")
    }

    private final class Cache { let lock = NSLock(); var values = [String: Double]() }
    private static let cache = Cache()
    static func cached(_ key: String) -> Double? { cache.lock.lock(); defer { cache.lock.unlock() }; return cache.values[key] }
    static func store(_ key: String, _ value: Double) { cache.lock.lock(); cache.values[key] = value; cache.lock.unlock() }
    /// For a test that measures a cold figure.
    static func clearCache() { cache.lock.lock(); cache.values = [:]; cache.lock.unlock() }
}

/// PvPoke's league score for a species (`pvp-rankings.json`, the same scores the advisor and the league tables use), for the PvP bar of a Pokémon the box has no copy of.
public struct PvpScores {
    private let byLeague: [String: [String: Double]]
    public init(data: Data) throws {
        struct Row: Decodable { var speciesId: String; var score: Double }
        struct File: Decodable { var leagues: [String: [Row]] }
        let f: File
        do { f = try JSONDecoder().decode(File.self, from: data) } catch { throw GameMaster.Failure.unreadable("pvp-rankings.json: \(error)") }
        byLeague = f.leagues.mapValues { Dictionary($0.map { ($0.speciesId, $0.score) }, uniquingKeysWith: { a, _ in a }) }
    }
    public init(byLeague: [String: [String: Double]]) { self.byLeague = byLeague }
    /// The score (0 to 100) of a species in a league (`gl`, `ul`, `ml`); nil when PvPoke does not rank it there.
    public func score(speciesId: String, league: String) -> Double? { byLeague[league]?[speciesId] }

    public static func bundled() throws -> PvpScores { try loaded.get() }
    private static let loaded = Result<PvpScores, Error> {
        guard let url = Bundle.module.url(forResource: "pvp-rankings", withExtension: "json") else { throw GameMaster.Failure.unreadable("pvp-rankings.json is missing from the app") }
        return try PvpScores(data: Data(contentsOf: url))
    }
}

/// The scale and the figures of one opened picker: the damage of each row's Pokémon against the slot's boss (or Rocket options), as a share of the best in the game for
/// that boss. The scale for a boss is kept (`shared`), with the figure of every row it has worked out, so a picker that is drawn again costs a lookup.
///
/// - Raids: damage per second against the boss from a simple cycle: n = ceil(charged cost / fast gain) fast moves, then the charged move (the better of the copy's charged
///   moves; fast moves alone if that is higher).
/// - Max: damage of one Max move: its type is the fast move's type; power is Max Attack level 1 (G-Max level 1, its own type, for a Gigantamax copy).
/// - Rocket: PvP stats, damage per turn of a fast-then-charged cycle with the 1.3 PvP bonus, averaged over the slot's possible Pokémon.
///
/// Which moves a Pokémon is judged on follows the boss: the best value against THIS boss over every move line the tables give for the Pokémon in this area (and the copy's
/// own read moves); never the line of the best tier. A line naming no known move is skipped and counted in `unparsedLines`.
public final class StrengthScale {
    public enum Mode: String { case raids, max, rocket }

    struct Target { var types: [String]; var defence: Double }
    /// A Pokémon as it fights: stats and typing of one species form at a level.
    struct Attacker { var speciesId: String; var base: BaseStats; var types: [String]; var shadow: Bool; var level: Double; var ivs: IVs }
    /// The best move combination found for an attacker and its value.
    struct Found { var value: Double; var fast: String?; var charged: String? }

    public let mode: Mode
    private let ctx: HubContext
    private let pve: PveMoves
    private let targets: [Target]
    /// Everything the best in the game depends on: the mode, the bosses, and fingerprints of the game master, the raid moves and the type chart.
    public let key: String
    private var best: Double?
    private var lineCache = [String: [DamageEstimate.Pick]]()
    private var memo = [String: Strength]()
    private let lock = NSRecursiveLock()
    /// How many table lines were skipped because they name no move the game master knows (counted as lines are first read).
    public private(set) var unparsedLines = 0

    /// `bosses` are the raid or Max battle's bosses, or the Rocket slot's possible Pokémon; the figure is the mean over them.
    public init(mode: Mode, bosses: [HubData.Boss], ctx: HubContext, pve: PveMoves) {
        self.mode = mode; self.ctx = ctx; self.pve = pve
        targets = bosses.map { b in
            let id = b.speciesId.hasSuffix("_shadow") ? String(b.speciesId.dropLast("_shadow".count)) : b.speciesId
            let def = Double(ctx.gm.byId[id]?.baseStats?.def ?? 180)
            return Target(types: b.types, defence: (def + DamageEstimate.defenderIV) * (PogoRules.cpm(DamageEstimate.defenderLevel) ?? 0.79))
        }
        let gmPrint = "\(ctx.gm.ordered.count)/\(ctx.gm.moves.count)/\(ctx.gm.ordered.reduce(0) { $0 &+ ($1.baseStats?.atk ?? 0) &* 3 &+ ($1.baseStats?.def ?? 0) })"
        let pvePrint = "\(pve.moves.count)/\(pve.maxAttackPower)/\(pve.gmaxPower)/\(pve.moves.values.reduce(0) { $0 + $1.power })"
        let chart = "\(ctx.hub.typeChart.values.reduce(0) { $0 + $1.count })/\(ctx.hub.typeChart.values.flatMap(\.values).reduce(0, +))"
        key = "\(mode.rawValue)|gm \(gmPrint)|pve \(pvePrint)|chart \(chart)|" + targets.map { "\($0.types.joined(separator: "+"))@\(Int($0.defence))" }.joined(separator: ",")
    }

    private static let sharedLock = NSLock()
    private static var sharedScales = [String: StrengthScale]()

    /// The kept scale for this boss: one per (mode, bosses), so reopening a picker, or drawing it again, reuses the best in the game and every row already worked out.
    public static func shared(mode: Mode, bosses: [HubData.Boss], ctx: HubContext, pve: PveMoves) -> StrengthScale {
        let fresh = StrengthScale(mode: mode, bosses: bosses, ctx: ctx, pve: pve)
        sharedLock.lock(); defer { sharedLock.unlock() }
        if let have = sharedScales[fresh.key] { return have }
        sharedScales[fresh.key] = fresh
        return fresh
    }

    // MARK: figures

    private func damage(_ type: String, power: Double, _ a: Attacker, _ t: Target, pvp: Bool = false) -> Double {
        guard let atk = DamageEstimate.attackStat(base: a.base, ivs: a.ivs, level: a.level, shadow: a.shadow) else { return 0 }
        return DamageEstimate.damage(power: power, attack: atk, defence: t.defence, sameType: a.types.contains(type), effectiveness: ctx.hub.effectiveness(type, against: t.types), pvp: pvp)
    }

    private func mean(_ f: (Target) -> Double) -> Double { targets.isEmpty ? 0 : targets.map(f).reduce(0, +) / Double(targets.count) }

    /// The species' own move ids, narrowed to `pick`. `strict`: a move the pick names that the species cannot learn rules the pick out (nil) instead of widening to all.
    private func lists(_ speciesId: String, _ pick: DamageEstimate.Pick, strict: Bool) -> (fast: [String], charged: [String])? {
        let s = ctx.gm.byId[speciesId] ?? ctx.gm.byId[speciesId.replacingOccurrences(of: "_shadow", with: "")]
        let fast = s?.fastMoves ?? [], charged = s?.chargedMoves ?? []
        var f = fast, c = charged
        if let pf = pick.fast {
            if fast.contains(pf) { f = [pf] } else if strict { return nil }
        }
        if !pick.charged.isEmpty {
            let known = pick.charged.filter(charged.contains)
            if !known.isEmpty { c = known } else if strict { return nil }
        }
        return (f, c)
    }

    /// The best value of one Pokémon over the move combinations `pick` leaves: DPS (Raids), one Max move's damage (Max) or damage per turn (Rocket). nil when the species has
    /// no usable move (or, strict, when the pick names moves it cannot learn).
    func value(_ a: Attacker, pick: DamageEstimate.Pick = .init(), gmaxType: String? = nil, strict: Bool = false) -> Double? { found(a, pick: pick, gmaxType: gmaxType, strict: strict)?.value }

    func found(_ a: Attacker, pick: DamageEstimate.Pick = .init(), gmaxType: String? = nil, strict: Bool = false) -> Found? {
        guard let (fast, charged) = lists(a.speciesId, pick, strict: strict) else { return nil }
        var top: Found?
        func offer(_ v: Double, _ f: String?, _ c: String?) { if v > (top?.value ?? -1) { top = Found(value: v, fast: f, charged: c) } }
        switch mode {
        case .max:
            // A Gigantamax copy's Max Attack is its G-Max move, of the G-Max type; any other copy's takes the type of its fast move.
            if let g = gmaxType { return Found(value: mean { damage(g, power: pve.gmaxPower, a, $0) }, fast: nil, charged: nil) }
            for fid in fast { if let t = ctx.gm.moves[fid]?.type { offer(mean { damage(t, power: pve.maxAttackPower, a, $0) }, fid, nil) } }
        case .raids:
            for fid in fast {
                guard let f = pve.moves[fid], f.energyDelta > 0, f.durationMs > 0 else { continue }
                // Fast moves alone, then each charged move in a cycle.
                offer(mean { damage(f.type, power: f.power, a, $0) / f.durationMs * 1000 }, fid, nil)
                for cid in charged {
                    guard let c = pve.moves[cid], c.energyDelta < 0, c.durationMs > 0 else { continue }
                    let n = (-c.energyDelta / f.energyDelta).rounded(.up)
                    offer(mean { t in (n * damage(f.type, power: f.power, a, t) + damage(c.type, power: c.power, a, t)) / (n * f.durationMs + c.durationMs) * 1000 }, fid, cid)
                }
            }
        case .rocket:
            for fid in fast {
                guard let f = ctx.gm.moves[fid], f.energyGain > 0, f.turns > 0 else { continue }
                offer(mean { damage(f.type, power: Double(f.power), a, $0, pvp: true) / Double(f.turns) }, fid, nil)
                for cid in charged {
                    guard let c = ctx.gm.moves[cid], c.energy > 0 else { continue }
                    let n = (Double(c.energy) / Double(f.energyGain)).rounded(.up)
                    offer(mean { t in (n * damage(f.type, power: Double(f.power), a, t, pvp: true) + damage(c.type, power: Double(c.power), a, t, pvp: true)) / (n * Double(f.turns) + 1) }, fid, cid)
                }
            }
        }
        return top
    }

    /// The best over several move lines (each tried strictly: a line the species cannot learn is skipped); no line left, the species' own best.
    func bestOver(_ a: Attacker, lines: [DamageEstimate.Pick], gmaxType: String? = nil) -> Found? {
        let tried = lines.compactMap { found(a, pick: $0, gmaxType: gmaxType, strict: true) }
        return tried.max { $0.value < $1.value } ?? found(a, gmaxType: gmaxType)
    }

    /// The best in the game for this boss: the strongest released species (`DamageEstimate.eligible`) at level 50 with 15/15/15 and its best legal moves, elite ones included;
    /// Shadow versions of the Shadow-eligible (Raids, Rocket; never of a Mega or Primal) and Mega forms (Raids); Max only the Dynamax-capable and Gigantamax species
    /// (`MaxBattleSpecies`) and the G-Max versions of those with a G-Max move.
    public var bestInGame: Double {
        if let b = best { return b }
        if let v = DamageEstimate.cached(key) { best = v; return v }
        let top = computeBest().value
        DamageEstimate.store(key, top)
        best = top
        return top
    }

    /// The best in the game and who it is (a test reads who): the species, whether as a Shadow, whether with its G-Max move.
    func computeBest() -> (value: Double, who: String, shadow: Bool, gmax: Bool) {
        var top = (value: 0.0, who: "", shadow: false, gmax: false)
        let capable = MaxBattleSpecies.capable
        for s in ctx.gm.ordered where DamageEstimate.eligible(s, megas: mode == .raids) {
            guard let base = s.baseStats else { continue }
            if mode == .max && !capable.contains(s.id) { continue }
            func a(_ shadow: Bool) -> Attacker { Attacker(speciesId: s.id, base: base, types: s.types, shadow: shadow, level: DamageEstimate.bestLevel, ivs: DamageEstimate.bestIVs) }
            func offer(_ v: Double?, shadow: Bool, gmax: Bool) { if let v, v > top.value { top = (v, s.id, shadow, gmax) } }
            offer(value(a(false)), shadow: false, gmax: false)
            // A Mega or Primal is never a Shadow: a Shadow cannot Mega Evolve.
            if mode != .max, s.tags.contains("shadoweligible"), !s.tags.contains("mega") { offer(value(a(true)), shadow: true, gmax: false) }
            if mode == .max, let g = MaxBattleSpecies.gigantamax[s.id] { offer(value(a(false), gmaxType: g), shadow: false, gmax: true) }
        }
        return top
    }

    private func share(_ v: Double?) -> Double? {
        guard let v, bestInGame > 0 else { return nil }
        return min(1, max(0, v / bestInGame))
    }

    // MARK: rows

    /// A picker row to estimate: the player's copy (and the build the row stands for, nil when none serves it), or a Pokémon the box lacks (`species`).
    public struct Row {
        public var copy: BoxEntry?
        public var build: BoxAdvice.Build?
        /// Full strength: no upgrade left, so no faint part.
        public var built: Bool
        /// True only in the raid Mega slot: the build's Mega Evolve step is taken. Every other slot judges the plain form.
        public var megaSlot: Bool
        /// A species the box lacks (Best): its game master id, whether it is a Shadow or a Gigantamax, and the table's move line.
        public var species: Lacking?
        public struct Lacking {
            public var speciesId: String
            public var shadow: Bool
            public var moves: String?
            public var gigantamax: Bool
            public init(speciesId: String, shadow: Bool, moves: String?, gigantamax: Bool = false) { self.speciesId = speciesId; self.shadow = shadow; self.moves = moves; self.gigantamax = gigantamax }
        }
        public init(copy: BoxEntry?, build: BoxAdvice.Build?, built: Bool, megaSlot: Bool = false, species: Lacking? = nil) {
            self.copy = copy; self.build = build; self.built = built; self.megaSlot = megaSlot; self.species = species
        }

        /// Everything the figure depends on, as a string, for the row memo.
        var signature: String {
            var p = [String]()
            if let c = copy {
                let r = c.row
                p += [c.id, r.speciesId, "\(r.level ?? -1)", r.ivs.map { "\($0.atk).\($0.def).\($0.hp)" } ?? "-", "\(r.shadow ?? -1)", "\(r.gigantamax == true)",
                      r.details.map { "\($0.fastMove ?? "-")|\($0.chargedMove ?? "-")|\($0.chargedMove2 ?? "-")" } ?? "-"]
            }
            if let b = build { p += [b.id, "\(b.targetLevel ?? -1)", "\(b.viaMega)", (b.steps ?? []).map { "\($0.kind)\($0.toLevel ?? 0)" }.joined(separator: ",")] }
            p += ["\(built)", "\(megaSlot)"]
            if let s = species { p += [s.speciesId, "\(s.shadow)", s.moves ?? "-", "\(s.gigantamax)"] }
            return p.joined(separator: "#")
        }
    }

    private func plain(_ id: String) -> String { id.hasSuffix("_shadow") ? String(id.dropLast("_shadow".count)) : id }

    func attacker(_ id: String, shadow: Bool, level: Double?, ivs: IVs?) -> Attacker? {
        let p = plain(id)
        guard let level, let ivs, let s = ctx.gm.byId[p], let base = s.baseStats else { return nil }
        // A Mega or Primal never has a Shadow's Attack: a Shadow never Mega Evolves.
        return Attacker(speciesId: p, base: base, types: s.types, shadow: shadow && !s.tags.contains("mega"), level: level, ivs: ivs)
    }

    /// The Mega or Primal forms a plain species takes (Charizard has two): the player would Mega Evolve into the better one against this boss.
    func megaSpecies(of id: String) -> [String] {
        ["_mega", "_mega_x", "_mega_y", "_primal"].map { plain(id) + $0 }.compactMap { ctx.gm.byId[$0] }.filter { $0.released && $0.tags.contains("mega") }.map(\.id)
    }

    /// Every table entry of this area for a Pokémon: all sections and tiers (its Mega entries when `mega`, the plain ones otherwise).
    func entries(of targetId: String, mega: Bool, shadow: Bool) -> [TierTable.Entry] {
        switch mode {
        case .raids: return HubRaidsModel.raidEntries(targetId: targetId, viaMega: mega, table: ctx.table, shadow: shadow).filter { $0.flags.mega == mega }
        case .max: return mega ? [] : HubRaidsModel.maxEntries(plain(targetId), ctx.table, gigantamax: false)
        case .rocket:
            guard !mega else { return [] }
            return (ctx.table.entries(for: targetId, area: "rocket") + (shadow ? ctx.table.entries(for: plain(targetId) + "_shadow", area: "rocket") : [])).filter { shadow || !$0.flags.shadow }
        }
    }

    /// The move lines of some entries, read once per text.
    func lines(_ entries: [TierTable.Entry]) -> [DamageEstimate.Pick] { entries.compactMap(\.moves).flatMap(picks(forText:)) }

    func picks(forText text: String) -> [DamageEstimate.Pick] {
        if let c = lineCache[text] { return c }
        let r = DamageEstimate.parseLines(text, gm: ctx.gm)
        unparsedLines += r.unparsed
        lineCache[text] = r.picks
        return r.picks
    }

    private func megaStep(_ b: BoxAdvice.Build) -> Bool { b.viaMega || (b.steps ?? []).contains { $0.kind == "megaEvolve" } }

    /// What `r` is worth against this boss, now and after its build.
    public func strength(_ r: Row) -> Strength {
        lock.lock(); defer { lock.unlock() }
        let sig = r.signature
        if let m = memo[sig] { return m }
        let s = compute(r)
        memo[sig] = s
        return s
    }

    private func compute(_ r: Row) -> Strength {
        if let sp = r.species {
            let a = attacker(sp.speciesId, shadow: sp.shadow, level: DamageEstimate.bestLevel, ivs: DamageEstimate.bestIVs)
            let g = sp.gigantamax && mode == .max ? MaxBattleSpecies.gigantamax[plain(sp.speciesId)] : nil
            let given = sp.moves.map(picks(forText:)) ?? []
            return Strength(kind: .damage, now: share(a.flatMap { bestOver($0, lines: given, gmaxType: g)?.value }), after: nil, assumed: true)
        }
        guard let copy = r.copy else { return Strength(kind: .damage, now: nil, after: nil) }
        let shadow = HubRaidsModel.isShadow(copy), gigantamax = copy.row.gigantamax == true
        let own = copy.row.details
        let ownPick = DamageEstimate.Pick(fast: own?.fastMove, charged: [own?.chargedMove, own?.chargedMove2].compactMap { $0 })
        let ownRead = ownPick.fast != nil || !ownPick.charged.isEmpty
        func gmax(_ id: String) -> String? { gigantamax && mode == .max ? MaxBattleSpecies.gigantamax[plain(id)] : nil }

        // Now: the copy's own species, level, IVs and Shadow state. Its own moves when read; otherwise the best of the table lines for the Pokémon against this boss.
        let nowSpecies = copy.row.speciesId
        let nowLines = ownRead ? [ownPick] : lines(entries(of: nowSpecies, mega: false, shadow: shadow))
        let now = share(attacker(nowSpecies, shadow: shadow, level: copy.row.level, ivs: copy.row.ivs).flatMap { bestOver($0, lines: nowLines, gmaxType: gmax(nowSpecies))?.value })

        // After: the build's target form (its Mega forms only in the Mega slot), the target level, and the best of its table lines (and the copy's own moves).
        var after: Double?
        if let b = r.build, !r.built {
            let mega = r.megaSlot && megaStep(b)
            let forms = mega ? megaSpecies(of: b.targetId) : []
            let level = b.targetLevel ?? b.climbLevel ?? copy.row.level
            let targets: [String] = forms.isEmpty ? [plain(b.targetId)] : forms
            after = targets.compactMap { t in
                // A Mega form's own table lines; the plain target's lines for any other.
                let own = mega && !forms.isEmpty ? entries(of: b.targetId, mega: true, shadow: shadow).filter { plain($0.speciesId) == t } : entries(of: b.targetId, mega: false, shadow: shadow)
                let given = lines(own) + (ownRead ? [ownPick] : [])
                return share(attacker(t, shadow: shadow, level: level, ivs: copy.row.ivs).flatMap { bestOver($0, lines: given, gmaxType: gmax(t))?.value })
            }.max()
            // An upgrade is never worse than the copy as it is.
            if let a = after, let n = now, a < n { after = n }
        }
        var s = Strength(kind: .damage, now: now, after: after)
        if !s.hasFaint && now != nil { s.after = nil }
        return s
    }
}

extension HubSquads {
    /// The table's move line for a Best row's entry in an area ("raids", "max", ...), for the estimate of a Pokémon the box lacks; nil when the entry names none.
    public static func tableMoves(of r: BestRow, area: String, ctx: HubContext) -> String? {
        ctx.table.entries(for: r.speciesId, area: area).first { bestKey($0) == r.key }?.moves
    }
}
